export type RouteRow = { airline: string; src: string; dest: string; count: number };

/**
 * Every known non-codeshare route, busiest first, packed as one string of
 * `AIRLINE|SRC|DEST:COUNT` records separated by `;`.
 *
 * Stored packed rather than as an array of objects because the raw form is
 * ~4x larger and this table is imported by the backend on every deploy. `count`
 * is a rough popularity signal, not a real frequency.
 * Server-side use only — it is deliberately not re-exported from index.ts so
 * it stays out of the browser bundle.
 */
export const routeRows: readonly RouteRow[] = parseRoutePack(ROUTE_PACK);

function parseRoutePack(pack: string): RouteRow[] {
  const out: RouteRow[] = [];
  for (const record of pack.split(";")) {
    if (!record) continue;
    const [keys, count] = record.split(":");
    const [airline, src, dest] = keys!.split("|");
    out.push({ airline: airline!, src: src!, dest: dest!, count: Number(count) });
  }
  return out;
}
